-- MealMate PostgreSQL schema (idempotent: safe to run on every startup).
-- IDs are UUID v4 values generated by the Node process (no extension needed).
-- Money values are whole MMK integers; calendar days use DATE columns.

CREATE TABLE IF NOT EXISTS users (
  id            uuid PRIMARY KEY,
  name          varchar(80)  NOT NULL,
  email         varchar(255) NOT NULL UNIQUE,
  password_hash text         NOT NULL,
  role          varchar(20)  NOT NULL DEFAULT 'user'
                CHECK (role IN ('user', 'admin')),
  is_active     boolean      NOT NULL DEFAULT true,
  last_login_at timestamptz,
  created_at    timestamptz  NOT NULL DEFAULT now(),
  updated_at    timestamptz  NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS foods (
  id          uuid PRIMARY KEY,
  name        varchar(100) NOT NULL,
  shop_name   varchar(100) NOT NULL,
  location    varchar(120) NOT NULL DEFAULT '',
  category    varchar(40)  NOT NULL
              CHECK (category IN ('Rice Dishes', 'Noodles', 'Soups', 'Salads', 'Others')),
  price       integer      NOT NULL CHECK (price >= 1 AND price <= 10000000),
  image_path  text,
  is_active   boolean      NOT NULL DEFAULT true,
  created_at  timestamptz  NOT NULL DEFAULT now(),
  updated_at  timestamptz  NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_foods_category_name ON foods (category, name);
CREATE INDEX IF NOT EXISTS idx_foods_shop_name ON foods (shop_name);
CREATE INDEX IF NOT EXISTS idx_foods_active ON foods (is_active);

CREATE TABLE IF NOT EXISTS favorites (
  id         uuid PRIMARY KEY,
  user_id    uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  food_id    uuid        NOT NULL REFERENCES foods (id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id, food_id)
);

CREATE INDEX IF NOT EXISTS idx_favorites_user ON favorites (user_id);

CREATE TABLE IF NOT EXISTS daily_budgets (
  id          uuid PRIMARY KEY,
  user_id     uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  budget_date date        NOT NULL,
  amount      integer     NOT NULL CHECK (amount >= 1 AND amount <= 10000000),
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id, budget_date)
);

CREATE INDEX IF NOT EXISTS idx_daily_budgets_user_date ON daily_budgets (user_id, budget_date);

CREATE TABLE IF NOT EXISTS meal_plans (
  id             uuid PRIMARY KEY,
  user_id        uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  plan_date      date        NOT NULL,
  method         varchar(10) NOT NULL CHECK (method IN ('auto', 'manual')),
  planned_total  integer     NOT NULL CHECK (planned_total >= 0 AND planned_total <= 10000000),
  budget_at_save integer     NOT NULL CHECK (budget_at_save >= 1 AND budget_at_save <= 10000000),
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id, plan_date)
);

CREATE INDEX IF NOT EXISTS idx_meal_plans_user_date ON meal_plans (user_id, plan_date);

-- Items keep an immutable snapshot of the catalog entry at save time.
-- food_id becomes NULL only if a catalog row is ever hard-deleted; the
-- snapshot columns (name/price/...) still render the saved plan.
CREATE TABLE IF NOT EXISTS meal_plan_items (
  id         uuid PRIMARY KEY,
  plan_id    uuid        NOT NULL REFERENCES meal_plans (id) ON DELETE CASCADE,
  sort_order integer     NOT NULL,
  food_id    uuid        REFERENCES foods (id) ON DELETE SET NULL,
  name       varchar(100) NOT NULL,
  shop_name  varchar(100) NOT NULL,
  category   varchar(40)  NOT NULL,
  image_path text,
  price      integer     NOT NULL CHECK (price >= 1 AND price <= 10000000),
  quantity   integer     NOT NULL CHECK (quantity >= 1 AND quantity <= 50),
  meal_type  varchar(20)  NOT NULL CHECK (meal_type IN ('breakfast', 'lunch', 'snacks', 'dinner'))
);

CREATE INDEX IF NOT EXISTS idx_meal_plan_items_plan ON meal_plan_items (plan_id, sort_order);

CREATE TABLE IF NOT EXISTS expense_days (
  id           uuid PRIMARY KEY,
  user_id      uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  expense_date date        NOT NULL,
  total        integer     NOT NULL CHECK (total >= 0 AND total <= 10000000),
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id, expense_date)
);

CREATE INDEX IF NOT EXISTS idx_expense_days_user_date ON expense_days (user_id, expense_date);

-- Manually entered actual-expense lines. They intentionally have no link to
-- the catalog or to meal plans (expenses are independent records).
CREATE TABLE IF NOT EXISTS expense_items (
  id             uuid PRIMARY KEY,
  expense_day_id uuid        NOT NULL REFERENCES expense_days (id) ON DELETE CASCADE,
  sort_order     integer     NOT NULL,
  name           varchar(100) NOT NULL,
  quantity       integer     NOT NULL CHECK (quantity >= 1 AND quantity <= 50),
  unit_price     integer     NOT NULL CHECK (unit_price >= 0 AND unit_price <= 10000000),
  meal_type      varchar(20)  NOT NULL CHECK (meal_type IN ('breakfast', 'lunch', 'snacks', 'dinner'))
);

CREATE INDEX IF NOT EXISTS idx_expense_items_day ON expense_items (expense_day_id, sort_order);
